import openpyxl

spreadsheet_path = sys.argv[1]
output_path = sys.argv[2]

wb = openpyxl.load_workbook(spreadsheet_path)
ws = wb['Sheet1']

# Build lookup: product code -> group from columns G and H (starting row 5)
lookup = {}
for row in ws.iter_rows(min_row=5):
    code = row[6].value  # G
    group = row[7].value  # H
    if code is not None and group is not None:
        lookup[str(code).strip()] = str(group).strip()

# Map group name to numeric index for ordering, then label ascending
def group_index(g):
    return int(str(g).split()[-1])

for r in range(5, 11):
    raw = ws.cell(row=r, column=3).value  # C
    if raw is None:
        continue
    parts = [p.strip() for p in str(raw).split(';') if p.strip()]
    groups = set()
    for p in parts:
        if p in lookup:
            groups.add(lookup[p])
    if not groups:
        continue
    group_list = sorted(groups, key=group_index)
    result = ', '.join(group_list)
    ws.cell(row=r, column=4).value = result  # D

wb.save(output_path)
print("Saved", output_path)", "path": "/bench/answers/48745/solution.py"}, "name": "write"}
